(x, y, t) => {
  const cx = 240, cy = 120;
  const n1 = Math.sin(x*0.023+t*0.31)*Math.cos(y*0.019-t*0.23)*18;
  const n2 = Math.cos(x*0.017-t*0.27)*Math.sin(y*0.021+t*0.37)*14;
  const n3 = Math.sin((x+y)*0.013+t*0.19)*Math.cos((x-y)*0.011-t*0.29)*10;
  const sx = x+n1+n3, sy = y+n2+n3;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 4],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 5],
    [80+Math.sin(t*0.45+3)*110, 100+Math.cos(t*0.65+2)*70, 0.11, 2.1, 0],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75+4)*60, 0.075, 1.8, 1],
    [200+Math.sin(t*0.38+6)*90, 30+Math.cos(t*0.48+3)*50, 0.095, 2.4, 2]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp,layer] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w = Math.sin(d*0.02-t*0.5)*0.3+1;
    const phase = layer*1.047;
    aS += Math.sin(d*f-t*sp+phase)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5+phase)*w;
    hS += Math.cos(d*f*0.5-t*sp*0.4+phase*0.5)*w*0.5;
  }
  const n = src.length;
  const act=aS/n, inh=iS/n, horm=hS/n;
  const bg1 = Math.sin(sx*0.04+sy*0.025+t*0.8);
  const bg2 = Math.sin(sx*0.03-sy*0.04+t*1.1);
  const bg3 = Math.sin((sx+sy)*0.12+t*2.5)*0.3;
  const bg4 = Math.sin((sx-sy)*0.1-t*2)*0.3;
  const bg5 = Math.sin(sx*0.065+Math.sin(sy*0.05+t)*2+t*0.9)*0.2;
  const bg = (bg1+bg2)/2+bg3+bg4+bg5;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.07-ang*2+t*0.8)*0.3;
  const spiral = (sp1+sp2)*0.4+sp3;
  const cellA = Math.sin(sx*0.15)*Math.sin(sy*0.15);
  const cellB = Math.sin((sx+sy)*0.1+t)*0.5;
  const cellC = Math.sin(sx*0.12-sy*0.08+t*0.7)*0.3;
  const cell = (cellA+cellB+cellC)/1.8;
  const coupling = act*inh*0.4 + horm*0.25;
  const feed = act - inh*0.7 + bg*0.25 + spiral*0.35 + cell*0.2 + coupling;
  const reaction = Math.tanh(feed*2.2);
  const lap = (bg1*bg2*0.15 + sp1*sp2*0.1);
  const diffused = Math.tanh((reaction + lap)*1.8);
  const edge = 1-Math.pow(1-Math.abs(diffused), 3)*0.3;
  const glow = Math.pow(Math.max(0, diffused), 3)*0.4;
  const v = diffused*0.5+0.5;
  const pal = [
    [5,12,52],[12,45,95],[18,85,125],[25,130,140],
    [60,165,145],[140,190,110],[210,195,70],[230,155,55],
    [215,105,60],[185,65,65],[140,35,75],[85,18,60],[40,10,45],[5,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const pulse = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const hiEdge = Math.abs(diffused)>0.72?1.2:Math.abs(diffused)>0.5?1.08:1.0;
  const lum = pulse*hiEdge*edge;
  const r = (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum + glow*180;
  const g = (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum + glow*160;
  const b = (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum + glow*100;
  return [Math.min(255,r)|0, Math.min(255,g)|0, Math.min(255,b)|0];
}
